package com.metavirtuoso.conjunction.core.p2p

import com.metavirtuoso.conjunction.core.p2p.Wire.arr
import com.metavirtuoso.conjunction.core.p2p.Wire.obj
import com.metavirtuoso.conjunction.core.p2p.Wire.str
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.time.LocalDate

/** Checks the Kotlin implementation against testdata/p2p_wire.json (generated by the Python reference). */
class P2pWireVectorsTest {
    private val root = Wire.root
    private val crypto = obj(root["crypto"])

    @Test
    fun uuidsAndFrameLengths() {
        val u = obj(root["uuids"])
        assertEquals(P2pConstants.SERVICE_UUID.toString(), u["service"])
        assertEquals(P2pConstants.INBOX_UUID.toString(), u["inbox"])
        assertEquals(P2pConstants.OUTBOX_UUID.toString(), u["outbox"])
        assertEquals(P2pConstants.PROTOCOL_VERSION.toLong(), root["protocolVersion"])
        for ((mtu, len) in obj(root["frameLenByMtu"])) assertEquals(len, P2pConstants.maxFrameLen(mtu.toInt()).toLong())
    }

    @Test
    fun messagesDecodeEncodeAndFrameIdentically() {
        val messages = arr(root["messages"]).map(::obj)
        assertTrue(messages.size >= 10)
        for (m in messages) {
            val name = str(m, "name")
            val body = unhex(str(m, "bodyHex"))
            val d = P2pMessages.decode(body)
            assertEquals(name, str(m, "json"), P2pMessages.canonicalJson(d.message))
            assertArrayEquals(name, unhex(str(m, "blobHex")), d.blob)
            assertArrayEquals(name, body, P2pMessages.encode(d.message, d.blob))
            // The canonical JSON text itself must parse to the same message.
            val again = P2pMessages.decode(FrameCodec.packBody(str(m, "json").toByteArray(), d.blob)).message
            assertEquals(name, d.message, again)
            for ((mtu, framesHex) in obj(m["framesByMtu"])) {
                val expected = arr(framesHex).map { unhex(it as String) }
                val got = FrameCodec.encode(0x0102, body, P2pConstants.maxFrameLen(mtu.toInt()))
                assertEquals("$name@$mtu count", expected.size, got.size)
                expected.zip(got).forEach { (e, g) -> assertArrayEquals("$name@$mtu", e, g) }
                val r = Reassembler()
                val out = expected.map { r.accept(it, 0) }
                assertArrayEquals(body, out.last())
                assertTrue(out.dropLast(1).all { it == null })
            }
        }
    }

    @Test
    fun invalidBodiesAreRejected() {
        for (c in arr(root["invalidBodies"]).map(::obj)) {
            try {
                P2pMessages.decode(unhex(str(c, "bodyHex")))
                fail("accepted invalid body: ${c["name"]}")
            } catch (e: P2pException) {
                assertEquals(c["name"].toString(), c["code"], e.code.wire)
            }
        }
    }

    @Test
    fun invalidFramesAreRejected() {
        for (c in arr(root["invalidFrames"]).map(::obj)) {
            try {
                Reassembler().accept(unhex(str(c, "hex")), 0)
                fail("accepted invalid frame: ${c["name"]}")
            } catch (e: P2pException) {
                assertEquals(c["name"].toString(), c["code"], e.code.wire)
            }
        }
    }

    @Test
    fun keysEcdhAndSession() {
        val keys = obj(crypto["keys"])
        for (n in listOf("identityA", "identityB", "ephemeralA", "ephemeralB")) {
            assertEquals(n, str(obj(keys[n]), "pub"), hexOf(Wire.key(n).publicKey))
            P2pCrypto.validatePoint(Wire.key(n).publicKey)
        }
        val ikA = Wire.key("identityA"); val ikB = Wire.key("identityB")
        val ekA = Wire.key("ephemeralA"); val ekB = Wire.key("ephemeralB")
        val ecdh = obj(crypto["ecdh"])
        assertEquals(ecdh["identity"], hexOf(ikA.agree(ikB.publicKey)))
        assertEquals(ecdh["identity"], hexOf(ikB.agree(ikA.publicKey)))
        assertEquals(ecdh["ephemeral"], hexOf(ekA.agree(ekB.publicKey)))

        val s = obj(crypto["session"])
        val order = obj(crypto["order"])
        val sa = P2pCrypto.deriveSession(ikA, ekA, ikB.publicKey, ekB.publicKey)
        val sb = P2pCrypto.deriveSession(ikB, ekB, ikA.publicKey, ekA.publicKey)
        assertEquals(order["identityAIsL"], sa.isL)
        assertEquals(s["transcriptSalt"], hexOf(sa.transcriptSalt))
        assertEquals(s["transcriptSalt"], hexOf(sb.transcriptSalt))
        assertEquals(s["okm"], hexOf(P2pCrypto.hkdf(unhex(str(s, "ikm")), sa.transcriptSalt, P2pCrypto.INFO_SESSION, 96)))
        val kLH = if (sa.isL) sa.sendKey else sa.recvKey
        val kHL = if (sa.isL) sa.recvKey else sa.sendKey
        assertEquals(s["kLH"], hexOf(kLH))
        assertEquals(s["kHL"], hexOf(kHL))
        assertEquals(s["kConf"], hexOf(sa.confKey))
        assertEquals(s["kcL"], hexOf(P2pCrypto.kcMac(sa.confKey, P2pCrypto.ROLE_L)))
        assertEquals(s["kcH"], hexOf(P2pCrypto.kcMac(sa.confKey, P2pCrypto.ROLE_H)))
        assertArrayEquals(sa.sendKey, sb.recvKey)
        assertArrayEquals(sa.myKc, sb.peerKc)
        assertEquals(s["kcMessageA"], P2pMessages.canonicalJson(P2pMessage.Kc(b64(sa.myKc))))

        for (h in arr(crypto["hkdf"]).map(::obj)) {
            assertEquals(h["okm"], hexOf(P2pCrypto.hkdf(unhex(str(h, "ikm")), unhex(str(h, "salt")), unhex(str(h, "info")), (h["length"] as Long).toInt())))
        }
    }

    @Test
    fun aesGcmVectorsAndTamper() {
        val vectors = arr(crypto["aesGcm"]).map(::obj)
        for (v in vectors) {
            val key = unhex(str(v, "key"))
            val ctr = v["ctr"] as Long
            assertEquals(v["nonce"], hexOf(P2pCrypto.nonce(ctr)))
            assertEquals(v["aadHex"], hexOf(P2pCrypto.CHAT_AAD))
            val ct = P2pCrypto.seal(key, ctr, str(v, "plaintext").toByteArray())
            assertEquals(v["ciphertextHex"], hexOf(ct))
            assertEquals(v["plaintext"], String(P2pCrypto.open(key, ctr, ct)))
            assertEquals(v["envelope"], P2pMessages.canonicalJson(P2pMessage.Chat(ctr, b64(ct))))
            val payload = P2pMessages.decodeChatPayload(str(v, "plaintext").toByteArray())
            assertEquals(v["plaintext"], String(P2pMessages.encodeChatPayload(payload)))
            for ((mtu, fr) in obj(v["framesByMtu"])) {
                val got = FrameCodec.encode(3, P2pMessages.encode(P2pMessage.Chat(ctr, b64(ct))), P2pConstants.maxFrameLen(mtu.toInt()))
                assertEquals(arr(fr), got.map(::hexOf))
            }
        }
        val key = unhex(str(vectors[0], "key"))
        try {
            P2pCrypto.open(key, 0, unhex(str(crypto, "tamperedCiphertextHex")))
            fail("tampered ciphertext accepted")
        } catch (e: P2pCryptoException) { /* expected */ }
        // Wrong counter (nonce) must fail too.
        try {
            P2pCrypto.open(key, 1, unhex(str(vectors[0], "ciphertextHex")))
            fail("wrong nonce accepted")
        } catch (e: P2pCryptoException) { /* expected */ }
    }

    @Test
    fun friendTagsSafetyCodeFingerprint() {
        val ikA = Wire.key("identityA"); val ikB = Wire.key("identityB")
        val f = obj(crypto["friend"])
        val fs = P2pCrypto.friendSecret(ikA, ikB.publicKey)
        assertEquals(f["friendSecret"], hexOf(fs))
        assertArrayEquals(fs, P2pCrypto.friendSecret(ikB, ikA.publicKey))
        for (t in arr(f["tags"]).map(::obj)) {
            val tag = P2pCrypto.friendTag(fs, str(t, "eid"))
            assertEquals(t["tagHex"], hexOf(tag))
            assertEquals(t["tagB64"], b64(tag))
        }
        assertEquals(crypto["safetyCode"], P2pCrypto.safetyCode(ikA.publicKey, ikB.publicKey))
        assertEquals(crypto["safetyCode"], P2pCrypto.safetyCode(ikB.publicKey, ikA.publicKey))
        for (fp in arr(crypto["profileFingerprint"]).map(::obj)) {
            val c = P2pMessages.decode(FrameCodec.packBody(("""{"t":"hello","pv":1,"pmin":1,"eid":"00000000000000000000000000000000","match":{"gender":"male","seeking":"both","relationship":"single","lookingFor":"both"},"compat":${fp["compat"]},"ft":[]}""").toByteArray()))
                .message as P2pMessage.Hello
            assertEquals(fp["fingerprint"], P2pCrypto.profileFingerprint(c.compat))
        }
    }

    @Test
    fun matchingGlue() {
        val m = obj(root["match"])
        val got = P2pMatching.evaluate(Wire.hello(str(m, "a")), Wire.hello(str(m, "b")), LocalDate.parse(str(m, "today")))
        assertNotNull(got)
        got!!
        assertEquals(m["kind"], got.kind.wire)
        assertEquals((m["total"] as Long).toInt(), got.score.total)
        assertEquals((m["western"] as Long).toInt(), got.score.western)
        assertEquals((m["chinese"] as Long).toInt(), got.score.chinese)
        assertEquals(m["blood"], got.score.blood?.toLong())
        assertEquals(m["isBirthdayTwin"], got.isBirthdayTwin)
        assertEquals(m["isExactTwin"], got.isExactTwin)
        assertEquals((m["peerAgeSeenByA"] as Long).toInt(), got.peerAge)
        assertEquals(m["highlights"], got.score.highlights)
        // Symmetric total.
        val back = P2pMatching.evaluate(Wire.hello(str(m, "b")), Wire.hello(str(m, "a")), LocalDate.parse(str(m, "today")))!!
        assertEquals(got.score.total, back.score.total)
        assertEquals(got.kind, back.kind)
    }

    @Test
    fun transcriptReplayAsPeripheral() = replay(LinkRole.PERIPHERAL)

    @Test
    fun transcriptReplayAsCentral() = replay(LinkRole.CENTRAL)

    /**
     * Plays one side of the Python transcript with the Kotlin state machine: the other side's frames
     * are fed in; everything Kotlin sends must equal the transcript (hello `ft` decoys excepted).
     */
    private fun replay(role: LinkRole) {
        val t = obj(root["transcript"])
        val me = if (role == LinkRole.CENTRAL) "central" else "peripheral"
        val cfg = obj(t[me])
        val hello = Wire.hello(str(cfg, "profile"))
        val photo = str(cfg, "photoHex").takeIf { it.isNotEmpty() }?.let(::unhex)
        val profile = profileOf(hello, str(cfg, "firstName"), cfg["bio"] as String?, photo)
        val now = t["nowMs"] as Long
        val link = P2pLink(role, profile, Wire.key(str(cfg, "identity")), TestPolicy(day = LocalDate.parse(str(t, "today"))),
            0, ephemeral = Wire.key(str(cfg, "ephemeral")))
        link.setAttMtu((t["attMtu"] as Long).toInt())
        link.start()
        val pending = ArrayDeque<ByteArray>()
        fun refill() { pending.addAll(link.takeFrames()) }
        refill()
        var checked = 0
        for (step in arr(t["steps"]).map(::obj)) {
            val action = step["action"] as String?
            if (action != null) {
                if (step["side"] != me) continue
                when (action) {
                    "swipe" -> link.swipe(SwipeDirection.entries.first { it.wire == step["dir"] })
                    "chat" -> link.sendChat(str(step, "text"), str(step, "id"), step["ts"] as Long)
                    "close" -> link.close(str(step, "reason"))
                }
                refill()
                continue
            }
            val frames = arr(step["frames"]).map { unhex(it as String) }
            if (step["from"] == me) {
                val got = (frames.indices).map { pending.removeFirstOrNull() ?: throw AssertionError("$me: missing frame for ${step["type"]}") }
                if (step["type"] == "hello") {
                    val a = P2pMessages.decode(got.joinBody()).message as P2pMessage.Hello
                    val e = P2pMessages.decode(frames.joinBody()).message as P2pMessage.Hello
                    assertEquals(e.copy(ft = emptyList()), a.copy(ft = emptyList()))
                    assertEquals(8, a.ft.size)
                } else {
                    frames.zip(got).forEach { (e, g) -> assertEquals("$me ${step["type"]}", hexOf(e), hexOf(g)) }
                }
                checked++
            } else {
                for (f in frames) link.onFrame(f, now)
                refill()
            }
        }
        val ev = link.takeEvents()
        assertTrue("$me: unexpected extra frames: ${pending.map { hexOf(it).take(40) }}", pending.isEmpty())
        assertEquals(if (role == LinkRole.CENTRAL) 9 else 7, checked)
        assertTrue(ev.any { it is LinkEvent.FriendEstablished })
        assertTrue(ev.any { it is LinkEvent.ChatReceived })
        assertTrue(ev.any { it is LinkEvent.Delivered })
        assertTrue(link.isClosed)
        assertFalse(ev.any { it is LinkEvent.ProtocolError })
    }

    private fun List<ByteArray>.joinBody(): ByteArray {
        val out = java.io.ByteArrayOutputStream()
        forEach { out.write(it, 7, it.size - 7) }
        return out.toByteArray()
    }
}
